"""Randomized stress test: every theorem checked on thousands of random instances.

For each random instance we verify, numerically and exactly where possible:

  T1  slab slopes equal block imbalances (the counting mechanism);
  T2  odd samples: L(m) + |t - m| <= L(t) with equality attained on the central slab;
  T3  even samples: the loss is constant exactly on [x_k, x_{k+1}] and grows with
      slope 2 outside, so that interval is exactly the minimizer set;
  T4  semigroup law and exact distance law for the clipped update;
  T5  finite termination at exactly ceil(|theta0 - target| / eta) steps, with no
      earlier iterate optimal;
  T6  the n-Lipschitz excess-risk envelope along the trajectory;
  T7  perturbed descent stays under max(eps, |u0 - m| - n(eta - eps));
  T8  separable multi-parameter descent halts at the box projection in
      max_i (coordinate times);
  T9  the two- and four-unit rectified forms reproduce the update exactly, and the
      curvature test finds exactly 2 resp. 4 separated kinks.

Run with:  python3 demo2.py
"""

from __future__ import annotations

import math
import random
from typing import Callable, List, Sequence, Tuple

TOL = 1e-9


def l1(xs: Sequence[float], t: float) -> float:
    return float(sum(abs(t - x) for x in xs))


def minset(xs: Sequence[float]) -> Tuple[float, float]:
    s = sorted(xs)
    n = len(s)
    if n % 2 == 1:
        k = (n - 1) // 2
        return s[k], s[k]
    k = n // 2 - 1
    return s[k], s[k + 1]


def proj(lo: float, hi: float, t: float) -> float:
    return max(lo, min(hi, t))


def flow(m: float, t: float, x: float) -> float:
    return min(m, x + t) if x < m else max(m, x - t)


def istep(lo: float, hi: float, eta: float, t: float) -> float:
    return flow(proj(lo, hi, t), eta, t)


def iterate(f: Callable[[float], float], n: int, x: float) -> float:
    for _ in range(n):
        x = f(x)
    return x


def relu(x: float) -> float:
    return max(x, 0.0)


def rand_sample(n: int) -> List[float]:
    return sorted(round(random.uniform(-10, 10), 3) for _ in range(n))


def main() -> None:
    random.seed(2026)
    trials = 4000
    fails = {f"T{i}": 0 for i in range(1, 10)}

    for _ in range(trials):
        n = random.randint(1, 9)
        xs = rand_sample(n)
        lo, hi = minset(xs)
        eta = round(random.uniform(0.1, 3.0), 3)
        th0 = round(random.uniform(-16, 16), 3)

        # T1 slab slopes = block imbalance
        for _ in range(3):
            p = random.uniform(-12, 12)
            q = p + random.uniform(0.01, 0.4)
            if any(p < x <= q for x in xs):
                continue
            low = sum(1 for x in xs if x <= 0.5 * (p + q))
            slope = (l1(xs, q) - l1(xs, p)) / (q - p)
            if abs(slope - (low - (n - low))) > 1e-6:
                fails["T1"] += 1

        # T2 odd growth bound
        if n % 2 == 1:
            m = lo
            for _ in range(6):
                t = random.uniform(-18, 18)
                if l1(xs, t) + TOL < l1(xs, m) + abs(t - m):
                    fails["T2"] += 1

        # T3 even flat interval and slope-2 growth
        if n % 2 == 0 and n > 0:
            base = l1(xs, lo)
            for _ in range(6):
                u = random.uniform(0, 1)
                if abs(l1(xs, lo + u * (hi - lo)) - base) > 1e-8:
                    fails["T3"] += 1
            d = random.uniform(0.1, 5)
            # growth of at least slope 2 in each direction (the theorem)
            if l1(xs, hi + d) + TOL < base + 2 * d or l1(xs, lo - d) + TOL < base + 2 * d:
                fails["T3"] += 1
            # exact slope 2 on the adjacent slabs, where no data point is crossed
            s = sorted(xs)
            k = n // 2 - 1
            up = (s[k + 2] - hi) if k + 2 < n else 1.0
            dn = (lo - s[k - 1]) if k - 1 >= 0 else 1.0
            du, dd = min(d, up), min(d, dn)
            if abs(l1(xs, hi + du) - (base + 2 * du)) > 1e-8:
                fails["T3"] += 1
            if abs(l1(xs, lo - dd) - (base + 2 * dd)) > 1e-8:
                fails["T3"] += 1

        # T4 semigroup and distance laws
        m = proj(lo, hi, th0)
        s, t = random.uniform(0, 4), random.uniform(0, 4)
        if abs(flow(m, s, flow(m, t, th0)) - flow(m, t + s, th0)) > 1e-9:
            fails["T4"] += 1
        k = random.randint(0, 12)
        if abs(abs(iterate(lambda z: flow(m, eta, z), k, th0) - m)
               - max(0.0, abs(th0 - m) - k * eta)) > 1e-9:
            fails["T4"] += 1

        # T5 exact stopping time and matching lower bound
        target = proj(lo, hi, th0)
        N = math.ceil(abs(th0 - target) / eta)
        step = lambda z: istep(lo, hi, eta, z)
        if abs(iterate(step, N, th0) - target) > 1e-9:
            fails["T5"] += 1
        if N > 0 and abs(iterate(step, N - 1, th0) - target) < 1e-12:
            fails["T5"] += 1

        # T6 excess-risk envelope
        for k in range(0, N + 2):
            th = iterate(step, k, th0)
            excess = l1(xs, th) - l1(xs, target)
            bound = n * max(0.0, abs(th0 - target) - k * eta)
            if excess < -TOL or excess > bound + 1e-8:
                fails["T6"] += 1

        # T7 perturbed bound
        eps = round(random.uniform(0, 1) * eta, 4)
        u, u0 = th0, th0
        for k in range(1, 14):
            u = flow(target, eta, u) + random.uniform(-eps, eps)
            if abs(u - target) > max(eps, abs(u0 - target) - k * (eta - eps)) + 1e-9:
                fails["T7"] += 1

        # T8 separable box descent
        d = random.randint(1, 4)
        coords = [rand_sample(2 * random.randint(1, 3)) for _ in range(d)]
        boxes = [minset(c) for c in coords]
        start = [random.uniform(-14, 14) for _ in range(d)]
        tgt = [proj(a, b, s0) for (a, b), s0 in zip(boxes, start)]
        times = [math.ceil(abs(s0 - g) / eta) for s0, g in zip(start, tgt)]
        theta = list(start)
        for _ in range(max(times)):
            theta = [istep(a, b, eta, z) for z, (a, b) in zip(theta, boxes)]
        if any(abs(z - g) > 1e-9 for z, g in zip(theta, tgt)):
            fails["T8"] += 1
        best = sum(l1(c, g) for c, g in zip(coords, tgt))
        for _ in range(20):
            cand = [random.uniform(-14, 14) for _ in range(d)]
            if sum(l1(c, z) for c, z in zip(coords, cand)) + 1e-9 < best:
                fails["T8"] += 1

        # T9 exact rectified forms and curvature counting
        mm = random.uniform(-5, 5)
        for _ in range(4):
            z = random.uniform(-15, 15)
            if abs(flow(mm, eta, z) - (mm + relu(z - mm - eta) - relu(mm - z - eta))) > 1e-9:
                fails["T9"] += 1
        if hi > lo:
            for _ in range(4):
                z = random.uniform(-20, 20)
                four = (z + eta - relu(z - (lo - eta)) + relu(z - lo)
                        - relu(z - hi) + relu(z - (hi + eta)))
                if abs(istep(lo, hi, eta, z) - four) > 1e-9:
                    fails["T9"] += 1

    print("randomized stress test over", trials, "instances")
    labels = {
        "T1": "counting mechanism: slab slope = block imbalance",
        "T2": "odd samples: linear growth away from the median",
        "T3": "even samples: flat central interval, slope 2 outside",
        "T4": "semigroup law and exact distance law",
        "T5": "exact stopping time with matching lower bound",
        "T6": "excess-risk envelope from Lipschitz control",
        "T7": "perturbed bound max(eps, |u0-m| - n(eta-eps))",
        "T8": "box minimizer set and coordinatewise termination",
        "T9": "exact two- and four-unit rectified forms",
    }
    for key, label in labels.items():
        status = "PASS" if fails[key] == 0 else f"FAIL ({fails[key]})"
        print(f"  {key}  {label:<52s} {status}")

    # curvature counting on a fixed pair of instances
    def sites(f: Callable[[float], float], a: float, b: float, h: float) -> int:
        out, last = 0, -1e9
        x = a
        while x <= b:
            if abs(f(x + h) + f(x - h) - 2 * f(x)) > 1e-9 and x - last >= 2 * h:
                out += 1
                last = x
            x += 0.004
        return out

    n2 = sites(lambda z: flow(0.0, 1.0, z), -6, 6, 0.5)
    n4 = sites(lambda z: istep(-1.0, 2.0, 1.0, z), -6, 8, 0.5)
    print(f"  curvature sites: point optimum -> {n2} (expect 2), segment optimum -> {n4} (expect 4)")


if __name__ == "__main__":
    main()

